parameters.jsCode:
// Parse incoming WAHA message
const body = $input.item.json.body || $input.item.json;
const message = body.payload?.body || body.message?.body || body.text || '';
const from = body.payload?.from || body.from || '';
const messageType = body.payload?.type || body.type || 'text';
const hasMedia = body.payload?.hasMedia || body.hasMedia || false;
const mediaUrl = body.payload?.mediaUrl || body.mediaUrl || '';

// Detect command type
let commandType = 'unknown';
let extractedData = {};

const lowerMessage = message.toLowerCase();

// Check for zakat mal calculation
if (lowerMessage.includes('hitung zakat mal') || lowerMessage.includes('zakat penghasilan')) {
  commandType = 'zakat_mal';
  // Extract amount from message
  const amountMatch = message.match(/(\d+[.,]?\d*)/g);
  if (amountMatch) {
    extractedData.penghasilan = parseFloat(amountMatch[0].replace(/\./g, '').replace(',', '.'));
  }
}
// Check for zakat fitrah calculation
else if (lowerMessage.includes('hitung zakat fitrah') || lowerMessage.includes('zakat fitrah')) {
  commandType = 'zakat_fitrah';
  // Extract number of people
  const peopleMatch = message.match(/(\d+)\s*(orang|jiwa|org)/i);
  if (peopleMatch) {
    extractedData.jumlahJiwa = parseInt(peopleMatch[1]);
  } else {
    extractedData.jumlahJiwa = 1;
  }
}
// Check for invoice/donation input
else if (lowerMessage.includes('no.liq') || lowerMessage.includes('noliq') || 
         lowerMessage.includes('nominal') || lowerMessage.includes('donasi') ||
         lowerMessage.includes('shodaqoh') || lowerMessage.includes('sedekah') ||
         lowerMessage.includes('infaq') || lowerMessage.includes('zakat')) {
  commandType = 'invoice_input';

  // Parse invoice data from NLP text
  // Pattern: no.liq xxx nominal 50ribu untuk shodaqoh

  // Extract no.liq
  const noLiqMatch = message.match(/no\.?\s*liq\s*[:#]?\s*([\w\d-]+)/i);
  extractedData.noLiq = noLiqMatch ? noLiqMatch[1].trim() : '';

  // Extract nama donatur (if mentioned)
  const namaMatch = message.match(/(?:dari|nama|donatur)\s*[:#]?\s*([^,\n]+?)(?=\s*(?:nominal|untuk|$))/i);
  extractedData.namaDonatur = namaMatch ? namaMatch[1].trim() : '';

  // Extract nominal
  let nominal = 0;
  const nominalMatch = message.match(/(?:nominal|rp\.?|idr)?\s*([\d.,]+)\s*(ribu|rb|juta|jt|k|m)?/i);
  if (nominalMatch) {
    nominal = parseFloat(nominalMatch[1].replace(/\./g, '').replace(',', '.'));
    const multiplier = nominalMatch[2]?.toLowerCase();
    if (multiplier === 'ribu' || multiplier === 'rb' || multiplier === 'k') {
      nominal *= 1000;
    } else if (multiplier === 'juta' || multiplier === 'jt' || multiplier === 'm') {
      nominal *= 1000000;
    }
  }
  extractedData.nominal = nominal;

  // Extract jenis (type of donation)
  let jenis = 'Lainnya';
  if (lowerMessage.includes('shodaqoh') || lowerMessage.includes('sedekah') || lowerMessage.includes('sodaqoh')) {
    jenis = 'Shodaqoh';
  } else if (lowerMessage.includes('infaq') || lowerMessage.includes('infak')) {
    jenis = 'Infaq';
  } else if (lowerMessage.includes('zakat fitrah')) {
    jenis = 'Zakat Fitrah';
  } else if (lowerMessage.includes('zakat mal') || lowerMessage.includes('zakat penghasilan')) {
    jenis = 'Zakat Mal';
  } else if (lowerMessage.includes('zakat')) {
    jenis = 'Zakat';
  } else if (lowerMessage.includes('wakaf')) {
    jenis = 'Wakaf';
  }
  extractedData.jenis = jenis;
}
// Check if it's an image (invoice image)
else if (hasMedia || messageType === 'image') {
  commandType = 'invoice_image';
  extractedData.mediaUrl = mediaUrl;
}

return {
  json: {
    from,
    message,
    messageType,
    hasMedia,
    mediaUrl,
    commandType,
    extractedData,
    timestamp: new Date().toISOString()
  }
};

// Parse OCR result and prepare for spreadsheet
const ocrResult = $input.item.json;
let extractedData = {};

try {
  // Try to parse JSON from OCR response
  const content = ocrResult.message?.content || ocrResult.choices?.[0]?.message?.content || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    extractedData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  extractedData = {
    noLiq: '',
    namaDonatur: '',
    nominal: 0,
    jenis: 'Lainnya'
  };
}

const originalData = $('Parse Message').item.json;

return {
  json: {
    ...originalData,
    extractedData: {
      noLiq: extractedData.noLiq || '',
      namaDonatur: extractedData.namaDonatur || '',
      nominal: parseFloat(extractedData.nominal) || 0,
      jenis: extractedData.jenis || 'Lainnya'
    }
  }
};

// Zakat Mal Calculator
// Nisab zakat mal = 85 gram emas (sekitar Rp 85.000.000 dengan asumsi harga emas Rp 1.000.000/gram)
// Tarif zakat mal = 2.5%

const NISAB_ZAKAT_MAL = 85000000; // Rp 85 juta (bisa disesuaikan dengan harga emas terkini)
const TARIF_ZAKAT = 0.025; // 2.5%

const penghasilan = $json.extractedData.penghasilan || 0;
const from = $json.from;

let responseMessage = '';
let zakatAmount = 0;
let wajibZakat = false;

if (penghasilan >= NISAB_ZAKAT_MAL) {
  wajibZakat = true;
  zakatAmount = penghasilan * TARIF_ZAKAT;
  responseMessage = `*Perhitungan Zakat Mal*\n\n` +
    `Penghasilan/Harta: Rp ${penghasilan.toLocaleString('id-ID')}\n` +
    `Nisab: Rp ${NISAB_ZAKAT_MAL.toLocaleString('id-ID')}\n` +
    `Status: WAJIB ZAKAT\n\n` +
    `*Zakat yang harus dibayar: Rp ${zakatAmount.toLocaleString('id-ID')}*\n` +
    `(2.5% x Rp ${penghasilan.toLocaleString('id-ID')})\n\n` +
    `Semoga Allah SWT menerima zakat Anda.`;
} else {
  responseMessage = `*Perhitungan Zakat Mal*\n\n` +
    `Penghasilan/Harta: Rp ${penghasilan.toLocaleString('id-ID')}\n` +
    `Nisab: Rp ${NISAB_ZAKAT_MAL.toLocaleString('id-ID')}\n` +
    `Status: BELUM WAJIB ZAKAT\n\n` +
    `Harta Anda belum mencapai nisab.\n` +
    `Namun Anda tetap bisa bersedekah.`;
}

return {
  json: {
    from,
    penghasilan,
    nisab: NISAB_ZAKAT_MAL,
    wajibZakat,
    zakatAmount,
    responseMessage
  }
};

// Zakat Fitrah Calculator
// Standar zakat fitrah = 2.5 kg atau 3.5 liter beras per jiwa
// Atau setara uang (harga beras ~Rp 15.000/kg x 2.5kg = Rp 37.500 per jiwa)

const HARGA_BERAS_PER_KG = 15000; // Rp 15.000/kg (bisa disesuaikan)
const BERAS_PER_JIWA_KG = 2.5; // 2.5 kg per jiwa
const ZAKAT_FITRAH_PER_JIWA = HARGA_BERAS_PER_KG * BERAS_PER_JIWA_KG; // Rp 37.500

const jumlahJiwa = $json.extractedData.jumlahJiwa || 1;
const from = $json.from;

const totalBeras = jumlahJiwa * BERAS_PER_JIWA_KG;
const totalUang = jumlahJiwa * ZAKAT_FITRAH_PER_JIWA;

const responseMessage = `*Perhitungan Zakat Fitrah*\n\n` +
  `Jumlah Jiwa: ${jumlahJiwa} orang\n` +
  `Zakat per jiwa: ${BERAS_PER_JIWA_KG} kg beras\n\n` +
  `*Total Zakat Fitrah:*\n` +
  `- Beras: ${totalBeras} kg\n` +
  `- Atau Uang: Rp ${totalUang.toLocaleString('id-ID')}\n` +
  `  (dengan asumsi harga beras Rp ${HARGA_BERAS_PER_KG.toLocaleString('id-ID')}/kg)\n\n` +
  `Catatan: Zakat fitrah wajib dikeluarkan sebelum shalat Idul Fitri.\n` +
  `Semoga Allah SWT menerima zakat Anda.`;

return {
  json: {
    from,
    jumlahJiwa,
    totalBeras,
    totalUang,
    responseMessage
  }
};

